68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email validation: a non-empty local part, a single '@', and a
73	     * domain with at least one dot-separated label ending in a letter-only TLD.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
77	
78	    /**
79	     * Disposable / throw-away email domains whose owners are rejected: an email on one of these
80	     * domains is treated as invalid input and rejected with 400. Compared case-insensitively.
81	     */
82	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
83	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
84	
85	    /**
86	     * Fixed public-holiday list. A registration date that lands on one of these is not a business
87	     * day and is rolled forward to the next non-holiday weekday.
88	     */
89	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS =
90	        java.util.Set.of(
91	            LocalDate.of(2026, 1, 1),
92	            LocalDate.of(2026, 1, 26),
93	            LocalDate.of(2026, 4, 25),
94	            LocalDate.of(2026, 12, 25),
95	            LocalDate.of(2026, 12, 28));
96	
97	    /** Dedicated audit logger for owner lifecycle side-effects. */
98	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
99	
100	    /** Request header carrying the client-supplied idempotency key for owner creation. */
101	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
102	
103	    /**
104	     * Remembers which owner was created for each already-seen idempotency key, so a repeated create
105	     * carrying a key seen before returns the originally created owner instead of creating a duplicate.
106	     */
107	    private final Map<String, Integer> idempotentCreations = new ConcurrentHashMap<>();
108	
109	    private final ClinicService clinicService;
110	
111	    private final OwnerMapper ownerMapper;
112	
113	    private final PetMapper petMapper;
114	
115	    private final VisitMapper visitMapper;
116	
117	    public OwnerRestControllerV1(ClinicService clinicService,
118	                                 OwnerMapper ownerMapper,
119	                                 PetMapper petMapper,
120	                                 VisitMapper visitMapper) {
121	        this.clinicService = clinicService;
122	        this.ownerMapper = ownerMapper;
123	        this.petMapper = petMapper;
124	        this.visitMapper = visitMapper;
125	    }
126	
127	    /**
128	     * Normalise a raw telephone number to E.164 form.
129	     *
130	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
131	     * code are kept when present; otherwise country code '+61' is assumed and a
132	     * single leading '0' is dropped from the national digits. The result must have
133	     * between 8 and 15 digits after the '+'.
134	     *
135	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
136	     * national-number length is additionally validated against that country code:
137	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
138	     * length is wrong for its country is rejected.
139	     *
140	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
141	     */
142	    static String toE164(String raw) {
143	        if (raw == null) {
144	            return null;
145	        }
146	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
147	        String digits;
148	        boolean explicitCountryCode;
149	        if (cleaned.startsWith("+")) {
150	            digits = cleaned.substring(1);
151	            explicitCountryCode = true;
152	        } else {
153	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
154	            digits = "61" + national;
155	            explicitCountryCode = false;
156	        }
157	        if (!digits.matches("[0-9]{8,15}")) {
158	            return null;
159	        }
160	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
161	            return null;
162	        }
163	        return "+" + digits;
164	    }
165	
166	    /**
167	     * Validate the national-number length of an E.164 number (its digits without the
168	     * leading '+') against the requirement for its country code: country code '+61'
169	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
170	     * without a configured length requirement are accepted unchanged.
171	     */
172	    private static boolean hasValidNationalLength(String digits) {
173	        if (digits.startsWith("61")) {
174	            return digits.length() - "61".length() == 9;
175	        }
176	        if (digits.startsWith("1")) {
177	            return digits.length() - "1".length() == 10;
178	        }
179	        return true;
180	    }
181	
182	    /**
183	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
184	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
185	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
186	     * input normalises to the empty string.
187	     */
188	    private static String normaliseIdentity(String value) {
189	        if (value == null) {
190	            return "";
191	        }
192	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
193	    }
194	
195	    /**
196	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
197	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
198	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
199	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
200	     * that is both stored and used for every address comparison.
201	     */
202	    static String normaliseAddress(String value) {
203	        if (value == null) {
204	            return "";
205	        }
206	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
207	        if (collapsed.isEmpty()) {
208	            return "";
209	        }
210	        String[] tokens = collapsed.split(" ");
211	        StringBuilder result = new StringBuilder();
212	        for (int i = 0; i < tokens.length; i++) {
213	            if (i > 0) {
214	                result.append(' ');
215	            }
216	            result.append(expandAddressAbbreviation(tokens[i]));
217	        }
218	        return result.toString();
219	    }
220	
221	    /**
222	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
223	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
224	     * returned unchanged.
225	     */
226	    private static String expandAddressAbbreviation(String token) {
227	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
228	        return switch (core) {
229	            case "ST" -> "STREET";
230	            case "RD" -> "ROAD";
231	            case "AVE" -> "AVENUE";
232	            default -> token;
233	        };
234	    }
235	
236	    /**
237	     * Derive the stable, shared household identifier for owners in the same household: the first 12
238	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
239	     * so every owner with the same last name and postcode resolves to the same value regardless of
240	     * the order in which they were created.
241	     */
242	    private static String householdId(String lastNameKey, String postcode) {
243	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
244	    }
245	
246	    /**
247	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
248	     * name and postcode). An owner without a postcode has no household peers and counts as a household
249	     * of one.
250	     */
251	    private int householdSize(Owner owner) {
252	        if (owner.getPostcode() == null) {
253	            return 1;
254	        }
255	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
256	        return (int) this.clinicService.findAllOwners().stream()
257	            .filter(existing -> existing.getPostcode() != null
258	                && householdId.equals(
259	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
260	            .count();
261	    }
262	
263	    /**
264	     * Build an owner's derived duplicate-detection identity key as
265	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
266	     * component contributes the empty string, and the email is lower-cased so the comparison is
267	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
268	     */
269	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
270	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
271	        String emailKey = email == null ? "" : email.toLowerCase();
272	        String household = householdId == null ? "" : householdId;
273	        return telephone + "|" + emailKey + "|" + household;
274	    }
275	
276	    /**
277	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
278	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
279	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
280	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
281	     * only on the owner's own region and identity, not on how many owners already exist.
282	     */
283	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
284	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
285	    }
286	
287	    /**
288	     * De-duplicate a computed customer code against the codes already assigned to existing owners:
289	     * when {@code code} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
290	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
291	     */
292	    private String deduplicateCustomerCode(String code) {
293	        Set<String> existing = this.clinicService.findAllOwners().stream()
294	            .map(Owner::getCustomerCode)
295	            .filter(Objects::nonNull)
296	            .collect(Collectors.toSet());
297	        if (!existing.contains(code)) {
298	            return code;
299	        }
300	        int n = 2;
301	        while (existing.contains(code + "-" + n)) {
302	            n++;
303	        }
304	        return code + "-" + n;
305	    }
306	
307	    /**
308	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
309	     */
310	    private static String hash8(String input) {
311	        return hashHex(input, 8, true);
312	    }
313	
314	    /**
315	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
316	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
317	     */
318	    private static String hashHex(String input, int length, boolean upperCase) {
319	        try {
320	            byte[] digest = MessageDigest.getInstance("SHA-256")
321	                .digest(input.getBytes(StandardCharsets.UTF_8));
322	            StringBuilder sb = new StringBuilder(digest.length * 2);
323	            for (byte b : digest) {
324	                sb.append(String.format("%02x", b));
325	            }
326	            String hex = sb.substring(0, length);
327	            return upperCase ? hex.toUpperCase() : hex;
328	        }
329	        catch (java.security.NoSuchAlgorithmException e) {
330	            throw new IllegalStateException(e);
331	        }
332	    }
333	
334	    /**
335	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
336	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
337	     * fixed city-to-region table, else {@code "UNKNOWN"}.
338	     */
339	    private static String region(String postcode, String city) {
340	        String fromPostcode = regionForPostcode(postcode);
341	        return fromPostcode != null ? fromPostcode : regionForCity(city);
342	    }
343	
344	    /**
345	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
346	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
347	     */
348	    private static String regionForPostcode(String postcode) {
349	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
350	            return null;
351	        }
352	        int value = Integer.parseInt(postcode);
353	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
354	            int[] range = entry.getValue();
355	            if (value >= range[0] && value <= range[1]) {
356	                return entry.getKey();
357	            }
358	        }
359	        return null;
360	    }
361	
362	    /**
363	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
364	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
365	     * weekday; ordinary weekday dates are returned unchanged.
366	     */
367	    static LocalDate toBusinessDay(LocalDate date) {
368	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
369	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
370	            || PUBLIC_HOLIDAYS.contains(date)) {
371	            date = date.plusDays(1);
372	        }
373	        return date;
374	    }
375	
376	    /**
377	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
378	     * using the same per-day accumulation path as the daily create-limit rule.
379	     */
380	    private long ownersCreatedOn(LocalDate registrationDate) {
381	        LocalDate day = toBusinessDay(registrationDate);
382	        return this.clinicService.findAllOwners().stream()
383	            .map(Owner::getRegistrationDate)
384	            .filter(existing -> existing != null)
385	            .map(OwnerRestControllerV1::toBusinessDay)
386	            .filter(day::equals)
387	            .count();
388	    }
389	
390	    /**
391	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
392	     * postcode against the owner's city region.
393	     */
394	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
395	        "NSW", new int[] {2000, 2099},
396	        "VIC", new int[] {3000, 3099},
397	        "QLD", new int[] {4000, 4099});
398	
399	    /**
400	     * Resolve an owner's region from the city using the fixed city-to-region table
401	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
402	     * when the city is not listed.
403	     */
404	    private static String regionForCity(String city) {
405	        return switch (city == null ? "" : city) {
406	            case "Sydney" -> "NSW";
407	            case "Melbourne" -> "VIC";
408	            case "Brisbane" -> "QLD";
409	            default -> "UNKNOWN";
410	        };
411	    }
412	
413	    /**
414	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
415	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
416	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
417	     */
418	    private static boolean isPostcodeValid(String postcode, String city) {
419	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
420	            return false;
421	        }
422	        int[] range = REGION_POSTCODES.get(regionForCity(city));
423	        if (range == null) {
424	            return true;
425	        }
426	        int value = Integer.parseInt(postcode);
427	        return value >= range[0] && value <= range[1];
428	    }
429	
430	    /**
431	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
432	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
433	     */
434	    private static boolean isDisposableEmailDomain(String email) {
435	        if (email == null) {
436	            return false;
437	        }
438	        int at = email.lastIndexOf('@');
439	        if (at < 0 || at == email.length() - 1) {
440	            return false;
441	        }
442	        String domain = email.substring(at + 1).toLowerCase();
443	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
444	    }
