476	    /**
477	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
478	     * request carries no such header (or there is no active servlet request). A blank value is treated
479	     * as absent.
480	     */
481	    private static String currentIdempotencyKey() {
482	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
483	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
484	            return null;
485	        }
486	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
