490	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
491	    @Override
492	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
493	        String idempotencyKey = currentIdempotencyKey();
494	        if (idempotencyKey != null) {
495	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
496	            if (existingId != null) {
497	                Owner existing = this.clinicService.findOwnerById(existingId);
498	                if (existing != null) {
499	                    existing.setHouseholdSize(householdSize(existing));
500	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
501	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
502	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
503	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
504	                }
505	            }
506	        }
507	        String telephone = toE164(ownerFieldsDto.getTelephone());
508	        if (telephone == null) {
509	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
510	        }
511	        String email = ownerFieldsDto.getEmail();
512	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
513	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
514	        }
515	        if (isDisposableEmailDomain(email)) {
516	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
517	        }
518	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
519	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
520	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
521	        // normalized addressLine2 appended after a single space when present.
522	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
523	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
524	        boolean structuredAddress = !addressLine1.isEmpty();
525	        String address;
526	        if (structuredAddress) {
527	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
528	        } else {
529	            address = normaliseAddress(ownerFieldsDto.getAddress());
530	        }
531	        if (address.isEmpty()) {
532	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
533	        }
534	        String postcode = ownerFieldsDto.getPostcode();
535	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
536	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
537	        }
538	        if (ownerFieldsDto.getRegistrationDate() != null
539	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
540	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
541	        }
542	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
543	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
544	        LocalDate registrationDate = toBusinessDay(effectiveDate);
545	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
546	            .map(Owner::getRegistrationDate)
547	            .filter(existing -> existing != null)
548	            .map(OwnerRestControllerV1::toBusinessDay)
549	            .filter(registrationDate::equals)
550	            .count();
551	        if (ownersCreatedThatDay >= 100) {
552	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
553	        }
554	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
555	        long ownersInCity = this.clinicService.findAllOwners().stream()
556	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
557	            .count();
558	        if (ownersInCity >= 50) {
559	            return new ResponseEntity<>(HttpStatus.CONFLICT);
560	        }
561	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
562	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
563	        // The household is deterministically keyed on (normalized last name, postcode): every owner
564	        // with a postcode belongs to the household identified by this computed id, and owners sharing
565	        // a last name and postcode share it automatically.
566	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
567	        // Existing owners already in this household (same last name and postcode). Soft-deleted
568	        // owners are ignored so a duplicate that only matches a deleted owner is allowed.
569	        List<Owner> householdMembers = (householdId == null) ? List.of()
570	            : this.clinicService.findAllOwners().stream()
571	                .filter(existing -> !existing.isDeleted())
572	                .filter(existing -> householdId.equals(
573	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
574	                .toList();
575	        // A second owner in an existing household is a household duplicate: rejected with 409 unless
576	        // it declares 'sharesHousehold', which only bypasses this block (the household link itself is
577	        // already assigned deterministically above).
578	        if (!householdMembers.isEmpty() && !sharesHousehold) {
579	            return new ResponseEntity<>(HttpStatus.CONFLICT);
580	        }
581	        String identityKey = identityKey(telephone, email, householdId);
582	        boolean identityInUse = this.clinicService.findAllOwners().stream()
583	            .filter(existing -> !existing.isDeleted())
584	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
585	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
586	        if (identityInUse) {
587	            return new ResponseEntity<>(HttpStatus.CONFLICT);
588	        }
589	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
590	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
591	            .filter(existing ->
592	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
593	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
594	            .count();
595	        HttpHeaders headers = new HttpHeaders();
596	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
597	        owner.setNamesakeCount(namesakeCount);
598	        owner.setAddress(address);
599	        if (structuredAddress) {
600	            owner.setAddressLine1(addressLine1);
601	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
602	        } else {
603	            owner.setAddressLine1(null);
604	            owner.setAddressLine2(null);
605	        }
606	        owner.setTelephone(telephone);
607	        owner.setEmail(email == null ? null : email.toLowerCase());
608	        owner.setRegistrationDate(registrationDate);
609	        owner.setCustomerCode(deduplicateCustomerCode(nextCustomerCode(
610	            region(postcode, owner.getCity()), telephone, owner.getLastName())));
611	        owner.setHouseholdId(householdId);
612	        // A created owner is never flagged as a suspected duplicate: a lone owner has no household
613	        // peer, and a same-household owner can only be created by declaring 'sharesHousehold', which
614	        // makes it an intentional household member rather than a suspected duplicate.
615	        owner.setPossibleDuplicateOf(null);
616	        this.clinicService.saveOwner(owner);
617	        if (idempotencyKey != null) {
618	            this.idempotentCreations.put(idempotencyKey, owner.getId());
619	        }
620	        owner.setHouseholdSize(householdSize(owner));
621	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
622	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
623	            ownerMapper.formatMembershipLevel(owner), ownerMapper.formatMembershipNumber(owner));
624	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
625	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
626	        headers.setLocation(UriComponentsBuilder.newInstance()
627	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
628	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
629	    }
