65	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
66	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
67	     * telephone, email or household id contributes the empty string in its position.
68	     */
69	    default String formatIdentityKey(Owner owner) {
70	        if (owner == null) {
71	            return null;
72	        }
73	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
74	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
75	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
76	        return telephone + "|" + email + "|" + householdId;
77	    }
