91	    /**
92	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
93	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
94	     * When the customer code is absent it falls back to resolving the region directly, preferring the
95	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
96	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
97	     * {@code "UNKNOWN"} when neither resolves.
98	     */
99	    default String formatLocality(Owner owner) {
100	        if (owner == null) {
101	            return null;
102	        }
103	        String code = owner.getCustomerCode();
104	        if (code != null) {
105	            int dash = code.indexOf('-');
106	            if (dash > 0) {
107	                return code.substring(0, dash);
108	            }
109	        }
110	        String fromPostcode = regionForPostcode(owner.getPostcode());
111	        if (fromPostcode != null) {
112	            return fromPostcode;
113	        }
114	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
115	            case "Sydney" -> "NSW";
116	            case "Melbourne" -> "VIC";
117	            case "Brisbane" -> "QLD";
118	            default -> "UNKNOWN";
119	        };
120	    }
121	
122	    /**
123	     * Derives an owner's IANA timezone from the locality (region) via the fixed region-to-timezone
124	     * table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
125	     * {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not one of these,
126	     * so the field is omitted from the response.
127	     */
128	    default String formatTimezone(Owner owner) {
129	        if (owner == null) {
130	            return null;
131	        }
132	        return switch (formatLocality(owner)) {
133	            case "NSW" -> "Australia/Sydney";
134	            case "VIC" -> "Australia/Melbourne";
135	            case "QLD" -> "Australia/Brisbane";
136	            default -> null;
137	        };
138	    }
139	
140	    /**
141	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
142	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
143	     * no known range, signalling that the caller should fall back to the city-to-region table.
144	     */
145	    private String regionForPostcode(String postcode) {
146	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
147	            return null;
148	        }
149	        int value = Integer.parseInt(postcode);
150	        if (value >= 2000 && value <= 2099) {
151	            return "NSW";
152	        }
153	        if (value >= 3000 && value <= 3099) {
154	            return "VIC";
155	        }
156	        if (value >= 4000 && value <= 4099) {
157	            return "QLD";
158	        }
159	        return null;
160	    }
161	
162	    /**
163	     * Computes an owner's membership points, starting at 0: plus 2 when an email is present, plus 1
164	     * when the owner's namesake count is 0, plus 2 for a household of 3 or more, plus 3 when the
165	     * owner's tenure exceeds 365 days.
166	     */
167	    default Integer formatMembershipPoints(Owner owner) {
168	        if (owner == null) {
169	            return null;
170	        }
171	        int points = 0;
172	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
173	        if (hasEmail) {
174	            points += 2;
175	        }
176	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
177	        if (unique) {
178	            points += 1;
179	        }
180	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
181	        if (largeHousehold) {
182	            points += 2;
183	        }
184	        boolean tenured = owner.getRegistrationDate() != null
185	            && fiscalYearStart(LocalDate.now()) - fiscalYearStart(owner.getRegistrationDate()) >= 1;
186	        if (tenured) {
187	            points += 3;
188	        }
189	        return points;
190	    }
191	
192	    /**
193	     * Derives an owner's membership level, a number from 1 to 4, from the owner's membership points:
194	     * 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
195	     */
196	    default Integer formatMembershipLevel(Owner owner) {
197	        if (owner == null) {
198	            return null;
199	        }
200	        int points = formatMembershipPoints(owner);
201	        if (points <= 1) {
202	            return 1;
203	        }
204	        if (points <= 3) {
205	            return 2;
206	        }
207	        if (points <= 5) {
208	            return 3;
209	        }
210	        return 4;
211	    }
