215	     * customer code. Returns {@code null} when the customer code is absent.
216	     */
217	    default Integer formatCheckDigit(Owner owner) {
218	        if (owner == null || owner.getCustomerCode() == null) {
219	            return null;
220	        }
221	        String code = owner.getCustomerCode();
222	        int sum = 0;
223	        boolean dbl = true;
224	        for (int i = code.length() - 1; i >= 0; i--) {
225	            char c = code.charAt(i);
226	            if (c < '0' || c > '9') {
227	                continue;
228	            }
229	            int d = c - '0';
230	            if (dbl) {
231	                d *= 2;
232	                if (d > 9) {
233	                    d -= 9;
234	                }
235	            }
236	            sum += d;
237	            dbl = !dbl;
238	        }
239	        return (10 - (sum % 10)) % 10;
240	    }
241	
242	    /**
243	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
244	     * digits of the fiscal year (starting 1 July) of the business-day-adjusted registration date
245	     * (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the customer code or registration
246	     * date is absent.
247	     */
248	    default String formatMembershipNumber(Owner owner) {
249	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
250	            return null;
251	        }
252	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearStart(owner.getRegistrationDate()) % 100);
253	    }
254	
255	    /**
256	     * Formats an owner's fiscal year as {@code 'FY<YY>'}, where YY is the last two digits of the
257	     * starting calendar year of the fiscal year (starting 1 July) that contains the owner's
258	     * business-day-adjusted registration date (e.g. 5 August 2026 yields {@code "FY26"} and 3 March
259	     * 2026 yields {@code "FY25"}). Returns {@code null} when the registration date is absent.
260	     */
261	    default String formatFiscalYear(Owner owner) {
262	        if (owner == null || owner.getRegistrationDate() == null) {
263	            return null;
264	        }
265	        return String.format("FY%02d", fiscalYearStart(owner.getRegistrationDate()) % 100);
266	    }
267	
268	    /**
269	     * Returns the starting calendar year of the fiscal year (which starts on 1 July) that contains
270	     * the given date: the date's own year when it falls on or after 1 July, otherwise the previous
271	     * year.
272	     */
273	    private int fiscalYearStart(LocalDate date) {
274	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
275	    }
276	
277	    /**
278	     * Formats an owner's stored E.164 telephone for humans as the country code, a space, and the
279	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
280	     * The raw {@code telephone} value stays in E.164 form. Returns the stored value unchanged when it
281	     * is {@code null} or not a well-formed E.164 string (a {@code '+'} followed by digits).
282	     */
283	    default String formatTelephoneDisplay(Owner owner) {
284	        if (owner == null) {
285	            return null;
286	        }
287	        String telephone = owner.getTelephone();
288	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
289	            return telephone;
290	        }
291	        String digits = telephone.substring(1);
292	        int countryCodeLength = countryCodeLength(digits);
293	        String countryCode = digits.substring(0, countryCodeLength);
294	        String national = digits.substring(countryCodeLength);
295	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
296	        for (int i = 0; i < national.length(); i += 3) {
297	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
298	        }
299	        return grouped.toString();
300	    }
301	
302	    /**
303	     * Determines the length of the country-code segment of an E.164 number's digits (its digits
304	     * without the leading {@code '+'}): 1 for the NANP ({@code '+1'}) and 2 otherwise (e.g. Australia's
305	     * {@code '+61'}), mirroring the country codes the application normalises to.
306	     */
307	    private int countryCodeLength(String digits) {
308	        return digits.startsWith("1") ? 1 : 2;
309	    }
310	
311	    /**
312	     * Formats an owner's canonical self link as {@code "/api/owners/" + id} from the stored id.
313	     * Returns {@code null} when the owner or its id is absent, so the field is omitted from the
314	     * response.
315	     */
316	    default String formatSelfLink(Owner owner) {
317	        if (owner == null || owner.getId() == null) {
318	            return null;
319	        }
320	        return "/api/owners/" + owner.getId();
321	    }
322	
323	    /**
324	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
325	     */
326	    default String formatDisplayName(Owner owner) {
327	        if (owner == null) {
328	            return null;
329	        }
330	        return owner.getLastName() + ", " + owner.getFirstName();
331	    }
332	
333	    /**
334	     * Formats an owner's salutation as the title and last name separated by a single space
335	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title
336	     * is given (null or blank). Returns {@code null} when the owner is {@code null}.
337	     */
338	    default String formatSalutation(Owner owner) {
339	        if (owner == null) {
340	            return null;
341	        }
342	        String title = owner.getTitle();
343	        if (title == null || title.isBlank()) {
344	            return owner.getLastName();
345	        }
346	        return title + " " + owner.getLastName();
347	    }
348	
349	    /**
350	     * Formats an owner's initials as the upper-cased first letters of the first and last
351	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
352	     */
353	    default String formatInitials(Owner owner) {
354	        if (owner == null) {
355	            return null;
356	        }
357	        return initial(owner.getFirstName()) + initial(owner.getLastName());
358	    }
359	
360	    private String initial(String name) {
361	        if (name == null || name.isEmpty()) {
362	            return "";
363	        }
364	        return Character.toUpperCase(name.charAt(0)) + ".";
365	    }
366	
367	    Owner toOwner(OwnerDto ownerDto);
368	
369	    @Mapping(target = "id", ignore = true)
370	    @Mapping(target = "pets", ignore = true)
371	    Owner toOwner(OwnerFieldsDto ownerDto);
372	
373	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
374	
375	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
376	
377	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
378	        OwnerPageDto ownerPageDto = new OwnerPageDto();
379	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
380	        ownerPageDto.setPage(ownerPage.getNumber());
381	        ownerPageDto.setSize(ownerPage.getSize());
382	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
383	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
384	        return ownerPageDto;
385	    }
386	}
